  const DURATION = 101.28;
  const LINES = [
    [0.8, "After Lord Shiva severed Brahma's fifth head, something unexpected happened.", "title", 5.12],
    [5.67, "Shiva's fierce form, Bhairava, had committed an act that carried a terrible consequence.", null, 10.57],
    [11.67, "Brahma was one of the divine creators, and killing him was considered the grave sin of Brahmahatya.", null, 17.12],
    [17.67, "As punishment, the sin itself took the form of a terrifying woman and began following Bhairava everywhere.", null, 23.28],
    [24.38, "Bhairava also became bound to Brahma's skull, which stuck to his hand.", null, 28.46],
    [29.01, "He could not get rid of it, no matter how hard he tried.", null, 32.24],
    [33.34, "Carrying Brahma's skull as a begging bowl, Lord Bhairava began wandering across the universe as a humble ascetic.", null, 39.73],
    [40.28, "He visited sacred places, seeking liberation from the burden of his sin.", null, 44.39],
    [45.49, "But the skull remained attached to his hand, and the spirit of Brahmahatya continued chasing him.", null, 50.89],
    [51.44, "Even the gods watched in wonder as the mighty Lord Shiva walked like a wandering beggar.", null, 55.95],
    [57.05, "Finally, Bhairava reached the holy city of Kashi, also known as Varanasi.", null, 61.83],
    [62.38, "The moment he entered the sacred land, Brahma's skull fell from his hand, and the terrible sin of Brahmahatya disappeared.", null, 69.06],
    [70.16, "The place where the skull fell became known as Kapala Mochana, the sacred place of liberation from the skull.", null, 75.78],
    [76.88, "Through this divine story, Kashi became associated with liberation, forgiveness, and freedom from even the greatest sins.", null, 84.29],
    [85.39, "Ending message: This is the mysterious story of what happened after Shiva cut off Brahma's fifth head.", "tag", 90.79],
    [91.34, "It reminds us that even divine actions carry cosmic consequences, and that Kashi holds a special place in Hindu tradition.", "tag", 98.28],
  ];
